/**
 * Flashcards for saved items: generated by the configured AI model when there
 * is one (answers checked against the item), otherwise cloze cards built on
 * the phone. Cards and their review schedule stay on this device.
 */

import { clozeCards, flashcardPrompt, flashcardSource, type CardDraft, type Grade, parseFlashcards, schedule, sourceEvidence } from '../core/flashcards';
import type { Card } from '../db/types';
import { loadProvider } from './ai';
import { noteCardReviewed } from './devFeeds';
import { getRepo } from './db';
import { emit } from './events';

export interface MakeCardsResult {
  /** Cards added now (existing questions are not duplicated). */
  added: number;
  /** All cards the item has after this call. */
  total: number;
  origin: Card['origin'] | null;
  /** Why the model was not used, or why no card could be made. */
  note: string | null;
}

export async function makeCards(itemId: string): Promise<MakeCardsResult> {
  const repo = await getRepo();
  const item = await repo.getItem(itemId);
  if (!item || item.deleted) throw new Error('Item not found.');
  const src = flashcardSource(item.title, item.enrichment);
  if (!src.tldr && !src.keyMoments.length) {
    return { added: 0, total: (await repo.listCards(itemId)).length, origin: null, note: 'This item has no summary or key moments yet.' };
  }
  let drafts: CardDraft[] = [];
  let origin: Card['origin'] = 'local';
  let note: string | null = null;
  const { provider, reason } = await loadProvider();
  if (provider) {
    try {
      const res = await provider.chat([{ role: 'user', content: flashcardPrompt(src) }], { maxTokens: 2500, temperature: 0.2 }); // room for reasoning models
      await repo.addUsage({ provider: provider.label, model: res.model, kind: 'flashcards', ...res.usage });
      drafts = parseFlashcards(res.content, sourceEvidence(src));
      if (drafts.length) origin = 'model';
      else note = 'The AI model gave no usable cards, so they were made on this phone.';
    } catch (e) {
      note = `AI unavailable (${(e as Error).message ?? e}); cards were made on this phone.`;
    }
  } else {
    note = reason;
  }
  if (!drafts.length) {
    drafts = clozeCards(item.enrichment);
    origin = 'local';
  }
  const added = await repo.addCards(itemId, drafts.map((d) => ({ ...d, origin })));
  const total = (await repo.listCards(itemId)).length;
  if (added.length) emit('cards');
  if (!drafts.length) note = [note, 'No concept or tool appears in the key moments, so no card could be made on this phone either.'].filter(Boolean).join(' ');
  return { added: added.length, total, origin: added.length ? origin : null, note };
}

export async function dueCards(limit = 20, collectionId?: string): Promise<Card[]> {
  return (await getRepo()).dueCards(new Date().toISOString(), limit, collectionId);
}

export async function dueCount(collectionId?: string): Promise<number> {
  return (await getRepo()).countDueCards(new Date().toISOString(), collectionId);
}

export async function gradeCard(cardId: string, grade: Grade, now = new Date()): Promise<Card | null> {
  const repo = await getRepo();
  const card = await repo.getCard(cardId);
  if (!card) return null;
  const next = schedule(card, grade, now);
  await repo.saveCardSchedule({ id: card.id, ...next });
  await noteCardReviewed().catch(() => undefined); // daily habit (Dev mode)
  emit('cards');
  return { ...card, ...next };
}
